screen.script:
const GEOMETRY_FONT = "javarailways:display_geometry";
const TEXT_FONT = "minecraft:default";
const G = { ring:"\uE004", dot:"\uE005" };
function object(v) { return v && typeof v === "object" && !Array.isArray(v) ? v : {}; }
function localized(v, lang, fallback) {
    if (typeof v === "string") return v;
    const m = object(v);
    return typeof m[lang] === "string" ? m[lang] : typeof m.zh === "string" ? m.zh : typeof m.en === "string" ? m.en : (fallback || "");
}
function color(v, fallback) { return typeof v === "string" && /^#[0-9a-fA-F]{6}$/.test(v) ? v : fallback; }
function span(parent, key, text, x, y, size, ink, font, layer, keepEmpty) {
    if (!text && !keepEmpty) return;
    const node = document.createElement("span");
    node.setAttribute("id", key);
    node.setAttribute("font", font || TEXT_FONT);
    // Centered TextDisplay adds one native font pixel to the line origin.
    x -= size / 9;
    node.setAttribute("style", "left:" + x + ";top:" + y + ";font-size:" + size + ";color:" + ink + ";z-index:" + (layer === undefined ? 30 : layer));
    node.textContent = String(text);
    parent.appendChild(node);
}
function rect(parent, key, left, top, width, height, ink, layer) {
    const node = document.createElement("rect");
    node.setAttribute("id", key);
    node.setAttribute("style", "left:" + left + ";top:" + top + ";width:" + width + ";height:" + height + ";color:" + ink + ";z-index:" + (layer === undefined ? 0 : layer));
    parent.appendChild(node);
}
function textUnits(text) {
    return Array.from(text).reduce((n, c) => n + (c.codePointAt(0) > 255 ? 1 : 0.7), 0);
}
function label(parent, key, text, x, y, maxSize, width, ink) {
    if (!text) return;
    const size = Math.min(maxSize, width / Math.max(1, textUnits(text)));
    span(parent, key, text, x, y + (maxSize - size) / 2, size, ink);
}
function readableLabel(parent, key, text, x, y, maxSize, minSize, width, ink, page, alignLeft = false, prefix = "") {
    if (!text) return;
    const prefixUnits = textUnits(prefix);
    const size = Math.max(minSize, Math.min(maxSize, width / Math.max(1, textUnits(text) + prefixUnits)));
    const capacity = width / size - prefixUnits;
    const pages = [];
    let rest = String(text).trim();
    while (rest) {
        const chars = Array.from(rest);
        let count = 0, units = 0;
        while (count < chars.length && units + textUnits(chars[count]) <= capacity) {
            units += textUnits(chars[count++]);
        }
        count = Math.max(1, count);
        if (count < chars.length) {
            // Prefer whole English words; unspaced station names split at a character boundary.
            const space = chars.slice(0, count + 1).lastIndexOf(" ");
            if (space > 0) count = space;
        }
        pages.push(chars.slice(0, count).join("").trim());
        rest = chars.slice(count).join("").trim();
    }
    if (!pages.length) return;
    const visible = prefix + pages[page % pages.length];
    // Estimate the centered default-font line width for left-aligned labels.
    if (alignLeft) x += Math.ceil(textUnits(visible) * 9) * size / 18;
    span(parent, key, visible, x, y + (maxSize - size) / 2, size, ink);
}
function data(ctx) {
    const op = object(ctx.data.operational);
    const run = object(op.currentRun);
    const rm = object(run.metadata);
    const line = object(object(ctx.data.lines)[run.lineId]);
    const lm = object(line.metadata);
    const lang = Math.floor(ctx.elapsedTicks / 180) % 2 === 0 ? "zh" : "en";
    return {op:op, run:run, rm:rm, line:line, lm:lm, lang:lang,
        theme:color(lm.themeColor, color(line.color, "#126EAA")),
        destination:localized(object(op.values).destination, lang, ""),
        service:localized(rm.class, lang, "")};
}

function localizedName(name, lang) {
    if (typeof name === "string") return name.trim() ? name : "";
    const translations = object(name);
    const zh = typeof translations.zh === "string" && translations.zh.trim() ? translations.zh : "";
    const en = typeof translations.en === "string" && translations.en.trim() ? translations.en : "";
    return lang === "zh" ? zh || en : en || zh;
}
function stationName(station, lang) {
    return localizedName(object(object(station).metadata).name, lang);
}
function transferLines(station, d, ctx) {
    const ids = object(object(station).metadata).transfers;
    if (!Array.isArray(ids)) return [];
    const catalog = object(ctx.data.lines);
    return ids.filter(id => typeof id === "string" && id !== d.run.lineId && catalog[id])
        .filter((id, i, all) => all.indexOf(id) === i).map(id => object(catalog[id]));
}
function transferBadge(parent, key, line, lang, x, y, width, height, size) {
    const metadata = object(line.metadata);
    const ink = color(metadata.themeColor, color(line.color, "#555555"));
    const text = localized(metadata.badge, lang, localizedName(metadata.name, lang) || line.id || "");
    rect(parent, key + "/background", x, y, width, height, ink, 20);
    label(parent, key + "/text", text, x + width / 2, y + (height - size) / 2 + 1, size, width - 4, "#FFFFFF");
}
function doorIcon(parent, side, right, bottom, theme, ticks) {
    if (!side) return;
    const x = right - 42, y = bottom - 40;
    const opensHere = side === "this" || side === "both";
    const ink = opensHere ? "#FFFFFF" : "#D6EDFF";
    const leafWidth = opensHere ? 6 : 17;

    rect(parent, "door/frame-top", x, y, 42, 3, ink, 20);
    rect(parent, "door/frame-bottom", x, y + 37, 42, 3, ink, 20);
    rect(parent, "door/frame-left", x, y + 3, 3, 34, ink, 20);
    rect(parent, "door/frame-right", x + 39, y + 3, 3, 34, ink, 20);
    rect(parent, "door/leaf-left", x + 3, y + 4, leafWidth, 32, ink, 20);
    rect(parent, "door/leaf-right", x + 39 - leafWidth, y + 4, leafWidth, 32, ink, 20);

    if (opensHere) {
        // Animate the exit cue while the door panels stay fully open.
        const spread = 4 + 4 * Math.min((ticks % 30) / 12, 1);
        span(parent, "door/arrow-left", "‹", x + 21 - spread, y + 8, 23, ink);
        span(parent, "door/arrow-right", "›", x + 21 + spread, y + 8, 23, ink);
    } else {
        rect(parent, "door/window-left", x + 6, y + 8, 11, 13, theme, 21);
        rect(parent, "door/window-right", x + 25, y + 8, 11, 13, theme, 21);
    }
}
function vertical(parent, key, text, x, y, size, rowsPerColumn, ink) {
    const chars = Array.from(text), capacity = rowsPerColumn * 2;
    const shown = chars.slice(0, capacity);
    if (chars.length > capacity) shown[capacity - 1] = "…";
    const columns = Math.ceil(shown.length / rowsPerColumn), pitch = size + 4;
    shown.forEach((char, i) => {
        const column = Math.floor(i / rowsPerColumn), row = i % rowsPerColumn;
        // Center the whole block; retain right-to-left column order for vertical names.
        span(parent, key + "/character/" + i, char, x + ((columns - 1) / 2 - column) * pitch,
            y + row * size, size, ink);
    });
}
function englishStation(parent, key, text, x, railY, slot, width, ink) {
    if (!text) return;
    const nominalSize = 18;
    let lines = [text], widest = textUnits(text);
    if (widest * nominalSize > width) {
        // Pick the word break that leaves the smallest maximum line width.
        const words = text.split(/\s+/);
        for (let split = 1; split < words.length; split++) {
            const first = words.slice(0, split).join(" ");
            const second = words.slice(split).join(" ");
            const candidate = Math.max(textUnits(first), textUnits(second));
            if (candidate < widest) {
                widest = candidate;
                lines = [first, second];
            }
        }
    }
    const top = railY + (slot % 2 === 0 ? 25 : 70);
    const stemTop = railY + 11;
    rect(parent, key + "/leader", x - 0.75, stemTop, 1.5, top - stemTop - 4, "#CBD3DA", 10);
    const size = Math.min(nominalSize, width / widest);
    lines.forEach((line, row) =>
        span(parent, key + "/line/" + row, line, x, top + row * 20, size, ink));
}
function render(ctx) {
    const d = data(ctx), op = d.op;
    if (d.run.isInService === false) return;
    const root = document.getElementById("content");
    const left = document.createElement("div"), right = document.createElement("div");
    root.appendChild(left); root.appendChild(right);
    // Fixed 42/58 split; readable principal text takes priority over excess whitespace.
    const panelWidth = 336;
    rect(left, "left-background", 0, 0, panelWidth, 200, d.theme);
    rect(right, "right-background", panelWidth, 0, 800 - panelWidth, 200, "#FFFFFF");
    const inset = 22;
    const contentWidth = panelWidth - 2 * inset;
    const badgeWidth = 102, badgeLeft = panelWidth - inset - badgeWidth;
    const ticks = ctx.elapsedTicks;
    const interval = Math.floor(ticks / 60);
    const languageWindow = interval % 3;
    const languageCycle = Math.floor(interval / 6);
    const page = languageCycle * 3 + languageWindow;
    const lineName = localizedName(d.rm.line, d.lang) || localizedName(d.lm.name, d.lang);
    const alternates = Boolean(lineName && d.destination);
    const showDestination = Boolean(d.destination) && (!lineName || interval % 2 === 1);
    // A 9-second language block gives the first field two slots and the other one.
    const firstField = showDestination === (d.lang === "en");
    const headerPage = alternates ? languageCycle * (firstField ? 2 : 1) + Math.floor(languageWindow / 2) : page;
    const headerPrefix = showDestination ? (d.lang === "zh" ? "开往 " : "For ") : "";
    readableLabel(left, "header", showDestination ? d.destination : lineName, inset, 15, 23, 23,
        d.service ? badgeLeft - inset - 12 : contentWidth, "#FFFFFF", headerPage, true, headerPrefix);
    if (d.service) {
        rect(left, "service-class-background", badgeLeft, 10, badgeWidth, 32, "#FFFFFF", 20);
        readableLabel(left, "service-class", d.service, badgeLeft + badgeWidth / 2, 15, 23, 23,
            badgeWidth - 12, "#183247", page);
    }
    const at = op.phase === "at_station";
    const station = at ? op.currentStation : op.nextStation;
    const stationCaption = d.lang === "zh" ? (at ? "本站" : "下一站") : (at ? "This station" : "Next station");
    readableLabel(left, "station-caption", stationCaption, inset, 60, 18, 18, contentWidth,
        "#D6EDFF", page, true);
    readableLabel(left, "station-name", stationName(station, d.lang), inset, 84, 46, 40, contentWidth,
        "#FFFFFF", page, true);
    const transfers = transferLines(station, d, ctx);
    if (transfers.length) {
        readableLabel(left, "transfer-caption", d.lang === "zh" ? "换乘" : "Transfer",
            inset, 137, 15, 15, contentWidth, "#D6EDFF", page, true);
        const perPage = 5, transferStart = page % Math.ceil(transfers.length / perPage) * perPage;
        transfers.slice(transferStart, transferStart + perPage).forEach((line, slot) => {
            transferBadge(left, "transfer/" + line.id, line, d.lang, inset + slot * 40, 158, 34, 26, 17);
        });
    }
    doorIcon(left, object(ctx.data.display).openingSide, panelWidth - inset, 184, d.theme, ticks);
    const calls = Array.isArray(op.stops) ? op.stops : [];
    const index = op.stationIndex;
    const known = (op.phase === "at_station" || op.phase === "in_transit") &&
        Number.isInteger(index) && index >= 0 && index < calls.length;
    if (!known) return;
    const slots = 8, start = Math.max(0, index - 2), shown = calls.slice(start, start + slots);
    const railY = 77, routeCenter = panelWidth + (800 - panelWidth) / 2;
    const spacing = Math.min(48, (800 - panelWidth - 64) / slots);
    const x0 = routeCenter - (shown.length - 1) * spacing / 2;
    const routeColor = color(d.line.color, d.theme), gray = "#A6ADB4";
    let nextStop = -1;
    const nextStart = at ? index + 1 : index;
    for (let i = nextStart; i < calls.length; i++) {
        if (calls[i].status === "STOP" || calls[i].status === "TERMINAL") { nextStop = i; break; }
    }
    // Stubs are visible only for genuinely omitted ordered occurrences; unresolved future is explicit too.
    if (start > 0) rect(right, "route-before", x0 - 28, railY - 2, 28, 4, gray, 10);
    if (start + shown.length < calls.length || (Array.isArray(op.unresolvedRuns) && op.unresolvedRuns.length))
        rect(right, "route-after", x0 + (shown.length - 1) * spacing, railY - 2, 28, 4, routeColor, 10);
    shown.forEach((call, slot) => {
        const key = "call/" + JSON.stringify([call.serviceId, call.runId, call.callId]);
        const absolute = start + slot, x = x0 + slot * spacing, passed = absolute < index;
        const ink = passed ? gray : routeColor;
        if (slot + 1 < shown.length) rect(right, key + "/route-after", x, railY - 2, spacing, 4,
            absolute < index ? gray : routeColor, 10);
        const transfers = transferLines(call, d, ctx), maxBadges = 3;
        transfers.slice(0, maxBadges).forEach((line, n) => {
            transferBadge(right, key + "/transfer/" + line.id, line, d.lang, x - 14, railY - 30 - n * 22, 28, 18, 12);
        });
        if (transfers.length > maxBadges) span(right, key + "/transfer-overflow", "+", x + 19, railY - 72, 11, "#333333");
        span(right, key + "/line-mask", G.dot, x, railY - 10, 20, "#FFFFFF", GEOMETRY_FONT, 19);
        span(right, key + "/ring", G.ring, x, railY - 10, 20, ink, GEOMETRY_FONT, 20);
        const stopping = call.status !== "PASS";
        if (stopping)
            span(right, key + "/dot", absolute !== nextStop || Math.floor(ctx.elapsedTicks / 10) % 2 === 0 ? G.dot : "",
                x, railY - 4, 8, ink, GEOMETRY_FONT, 21, true);
        const name = stationName(call, d.lang), muted = passed || !stopping;
        if (d.lang === "zh")
            vertical(right, key + "/name", name, x, railY + 17, 22, 4, muted ? gray : "#202830");
        else
            englishStation(right, key + "/name", name, x, railY, slot, 2 * spacing - 10, muted ? "#626C76" : "#202830");
    });
}
